defineOptions({ inheritAttrs: false });

const props = withDefaults(
  defineProps<{
    x: number;
    y: number;
    z?: number | string;
    dragHandle?: string;
    disabled?: boolean;
  }>(),
  {
    z: 'auto',
    dragHandle: '',
    disabled: false,
  },
);

