.mimi-phone-wrapper {
  pointer-events: auto !important;
  width: min(390px, calc(100vw - 32px));
  max-width: 390px;
}

.mimi-phone-container {
  position: relative;
  width: 100%;
  aspect-ratio: 9 / 18.6;
  display: flex;
  justify-content: center;
  align-items: stretch;
  flex-shrink: 0;
  filter: drop-shadow(0 24px 38px rgba(12, 20, 38, 0.32));
  pointer-events: auto;
  overflow: hidden;
  max-width: 100%;
}

.mimi-phone-container::before,
.mimi-phone-container::after {
  content: '';
  position: absolute;
  background: linear-gradient(90deg, #444954, #1c1f27);
  border-radius: 4px;
  width: 3px;
}

.mimi-phone-container::before {
  left: -6px;
  top: 24%;
  height: 60px;
  box-shadow: 0 74px 0 0 rgba(60, 65, 78, 0.85);
}

.mimi-phone-container::after {
  right: -6px;
  top: 32%;
  height: 96px;
}

.mimi-phone-frame {
  position: relative;
  flex: 1;
  border-radius: 38px;
  padding: 14px;
  background: linear-gradient(145deg, #1f2129 0%, #090a0f 100%);
  box-shadow:
    inset 0 0 0 1px rgba(255, 255, 255, 0.08),
    inset 0 0 0 6px rgba(30, 32, 40, 0.9),
    0 18px 45px rgba(3, 6, 12, 0.4);
  display: flex;
  align-items: stretch;
}

.mimi-phone-notch {
  position: absolute;
  top: 12px;
  left: 50%;
  transform: translateX(-50%);
  width: 42%;
  height: 18px;
  background: linear-gradient(180deg, rgba(14, 16, 20, 0.95) 0%, rgba(6, 7, 10, 0.95) 100%);
  border-radius: 0 0 16px 16px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 18px;
  box-shadow: inset 0 -1px 0 rgba(255, 255, 255, 0.06);
}

.mimi-phone-notch__speaker {
  width: 50%;
  height: 4px;
  border-radius: 99px;
  background: linear-gradient(90deg, rgba(70, 76, 88, 0.9), rgba(110, 118, 130, 0.65));
}

.mimi-phone-notch__camera {
  position: relative;
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: radial-gradient(circle at 30% 30%, #3fd4ff, #0a1a2e 70%);
  box-shadow: 0 0 6px rgba(63, 212, 255, 0.55);
}

.mimi-phone-frame__inner {
  position: relative;
  flex: 1;
  width: 100%;
  border-radius: 28px;
  background: linear-gradient(180deg, #f6f7ff 0%, #f1f3ff 50%, #e8ebff 100%);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  box-sizing: border-box;
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.25);
}

.mimi-phone-drag-handle {
  cursor: move;
  user-select: none;
  pointer-events: auto;
  transition: none;
  /* 移动端触摸优化 */
  touch-action: none;
  -webkit-tap-highlight-color: transparent;
}

.mimi-phone-drag-handle * {
  transition: none;
}

.mimi-phone-status-bar {
  height: 44px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 0 24px;
  font-size: 14px;
  font-weight: 600;
  cursor: grab;
  user-select: none;
  transition:
    background-color 0.2s ease,
    color 0.2s ease;
}

.mimi-phone-status-bar:active {
  cursor: grabbing;
}

.mimi-phone-status-bar:hover {
  background-color: rgba(255, 255, 255, 0.05);
}

.mimi-phone-status-bar:active {
  background-color: rgba(255, 255, 255, 0.1);
}

.mimi-phone-screen {
  flex: 1;
  width: 100%;
  position: relative;
  z-index: 1;
  display: flex;
  flex-direction: column;
  min-height: 0;
  box-sizing: border-box;
  overflow: hidden;
}

.mimi-home-page {
  position: relative;
  flex: 1;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  padding: 32px 22px 42px;
  box-sizing: border-box;
  color: #202432;
  background: linear-gradient(
    180deg,
    rgba(246, 248, 255, 0.82) 0%,
    rgba(240, 242, 255, 0.92) 60%,
    rgba(229, 233, 255, 0.96) 100%
  );
}

.mimi-home-header {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 6px;
  padding-top: 12px;
}

.mimi-home-clock {
  font-size: clamp(52px, 16vw, 64px);
  line-height: 1;
  font-weight: 600;
  letter-spacing: 1px;
}

.mimi-home-date {
  font-size: 16px;
  color: rgba(32, 36, 50, 0.6);
  letter-spacing: 0.4px;
}

.mimi-home-app-grid {
  display: flex;
  flex-wrap: wrap;
  gap: 28px 22px;
  padding-top: 16px;
  flex: 1;
  align-content: flex-start;
}

.mimi-app-card {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
  background: none;
  border: none;
  cursor: pointer;
  padding: 0;
}

.mimi-app-card__icon {
  width: 74px;
  height: 74px;
  border-radius: 22px;
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: 0 12px 30px rgba(49, 55, 82, 0.22);
}

.mimi-app-card__icon svg {
  width: 34px;
  height: 34px;
  fill: #ffffff;
}

.mimi-app-card--chat .mimi-app-card__icon {
  background: linear-gradient(140deg, #5b86e5 0%, #36d1dc 100%);
}

.mimi-app-card--settings .mimi-app-card__icon {
  background: linear-gradient(140deg, #65748b 0%, #434f63 60%, #2d3647 100%);
}

.mimi-app-card__label {
  font-size: 14px;
  letter-spacing: 0.4px;
  color: rgba(32, 36, 50, 0.9);
}

.mimi-home-dock {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 14px;
  padding-bottom: 6px;
}

.mimi-home-dock__glass {
  width: 100%;
  border-radius: 26px;
  padding: 12px 18px;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 18px;
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.65) 0%, rgba(238, 242, 255, 0.82) 100%);
  box-shadow:
    inset 0 0 0 1px rgba(255, 255, 255, 0.4),
    0 10px 30px rgba(90, 104, 149, 0.18);
}

.mimi-dock-app {
  width: 54px;
  height: 54px;
  border-radius: 18px;
  border: none;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  box-shadow: 0 10px 22px rgba(62, 78, 130, 0.24);
  transition: transform 0.15s ease;
  padding: 0;
}

.mimi-dock-app:active {
  transform: scale(0.94);
}

.mimi-dock-app svg {
  width: 26px;
  height: 26px;
  fill: #ffffff;
}

.mimi-dock-app--phone {
  background: linear-gradient(150deg, #40e19d 0%, #1dbf79 100%) !important;
}

.mimi-dock-app--message {
  background: linear-gradient(150deg, #5aa9ff 0%, #306dff 100%) !important;
}

.mimi-dock-app--gallery {
  background: linear-gradient(150deg, #ff8abb 0%, #ff5f7d 100%) !important;
}

.mimi-dock-app--music {
  background: linear-gradient(150deg, #ffb064 0%, #ff7b45 100%) !important;
}

.mimi-home-dock__indicator {
  width: 110px;
  height: 5px;
  border-radius: 999px;
  background: rgba(35, 40, 55, 0.16);
}

.mimi-app-card:focus-visible,
.mimi-dock-app:focus-visible {
  outline: 2px solid rgba(88, 116, 255, 0.35);
  outline-offset: 4px;
}
