.mimi-moments-page {
  display: flex;
  flex-direction: column;
  flex: 1;
  min-height: 0;
  background: #f6f6f7;
  /* 隐藏滚动条 */
  scrollbar-width: none;
  -ms-overflow-style: none;
  width: 100%;
  max-width: 100%;
  overflow: hidden;
}

.mimi-moments-page::-webkit-scrollbar {
  width: 0;
  height: 0;
}

.mimi-moments-view,
.mimi-publish-view {
  display: flex;
  flex-direction: column;
  flex: 1;
  min-height: 0;
  width: 100%;
  max-width: 100%;
  overflow: hidden;
}

.mimi-moments-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 16px 12px;
  width: 100%;
  box-sizing: border-box;
  background: #ffffff;
  border-bottom: 1px solid #e8e8ea;
  color: #1f1f1f;
  cursor: default;
  user-select: none;
}

.mimi-moments-title {
  font-weight: 600;
  font-size: 16px;
}

.mimi-header-button {
  display: flex;
  align-items: center;
  justify-content: center;
  border: none;
  background: none;
  color: #424249;
  padding: 4px;
  cursor: pointer;
  transition: color 0.2s ease;
}

.mimi-header-button:hover {
  color: #1f1f1f;
}

.mimi-header-button svg {
  width: 32px;
  height: 32px;
}

.mimi-actions {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-left: auto;
}

.mimi-icon-button {
  border: none;
  background: none;
  color: #444;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 0;
  cursor: pointer;
}

.mimi-icon-button svg {
  width: 32px;
  height: 32px;
}

.mimi-moments-list {
  flex: 1;
  overflow-y: auto;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 12px;
  background-color: #ffffff;
  /* 隐藏滚动条 */
  scrollbar-width: none;
  -ms-overflow-style: none;
}

.mimi-moment-card {
  background-color: #fff;
  padding: 16px;
  display: flex;
  flex-direction: column;
  gap: 12px;
  border-bottom: 1px solid #ededf0;
}

.mimi-moment-card-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 12px;
}

.mimi-moment-user {
  display: flex;
  gap: 12px;
  align-items: center;
}

.mimi-moment-avatar {
  width: 42px;
  height: 42px;
  border-radius: 50%;
  object-fit: cover;
  border: 1px solid #e5e5e8;
}

.mimi-moment-user-info {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.mimi-moment-name {
  font-weight: 600;
  color: #1f1f1f;
}

.mimi-moment-timestamp {
  font-size: 12px;
  color: #9b9b9f;
}

.mimi-moment-more {
  border: none;
  background: none;
  color: #9b9b9f;
  cursor: pointer;
  padding: 4px;
}

.mimi-moment-more svg {
  width: 16px;
  height: 16px;
}

.mimi-moment-body {
  display: flex;
  flex-direction: column;
  gap: 8px;
  align-items: flex-start;
}

.mimi-moment-content {
  color: #2c2c2e;
  font-size: 16px;
  line-height: 1.5;
  margin: 0;
}

.mimi-moment-comments {
  margin: 0;
  padding: 8px 0;
  border-radius: 12px;
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 6px;
  color: #4c4c52;
  font-size: 15px;
}

.mimi-moment-comment {
  line-height: 1.4;
}

.mimi-moment-comment-author {
  color: #3271ff;
  font-weight: 500;
}

.mimi-moment-reply {
  margin-top: 4px;
}

.mimi-moment-reply-input {
  width: 100%;
  padding: 10px 12px;
  border: none;
  border-radius: 12px;
  background-color: #f3f4f6;
  color: #2c2c2e;
  font-size: 14px;
  outline: none;
}

.mimi-moment-reply-input::placeholder {
  color: #9b9b9f;
}

.mimi-empty-state {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;
  color: #9b9b9f;
  padding: 32px;
}

.mimi-empty-state svg {
  width: 48px;
  height: 48px;
}

/* WebKit 隐藏滚动条 */
.mimi-moments-list::-webkit-scrollbar {
  width: 0;
  height: 0;
}

/* 手机应用输入框样式隔离 */
.mimi-moments-page input[type='text'],
.mimi-moments-page input[type='number'],
.mimi-moments-page input:not([type]),
.mimi-moments-page textarea:not([type='search']) {
  background-color: #f3f4f6 !important;
  border: none !important;
  color: #2c2c2e !important;
}

.mimi-moments-page .mimi-moment-reply-input {
  background-color: #f3f4f6 !important;
  border: none !important;
  color: #2c2c2e !important;
}

.mimi-moments-page .mimi-moment-reply-input::placeholder {
  color: #9b9b9f !important;
}
